// ============================================================================
// Test Harness — HITL Gateway smoke test
// ----------------------------------------------------------------------------
// Simulates a flagship REQUIRE_HUMAN execution rollup payload to exercise
// the gateway end-to-end without running the full flagship.
//
// Uses Aisha as the invoker (FP&A Lead) so when we later test the SoD
// trigger from the Approval Handler, Aisha's attempt to approve fires
// FAO-GOV-004 (loud) and Sarah's attempt succeeds. The choice of invoker
// is intentional and architecturally meaningful, not arbitrary.
//
// Each test run must use a unique correlation_id because hitl_queue has
// UNIQUE(correlation_id). UUID v4 inline (same pattern as flagship Init).
// ============================================================================

const randomUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

return [{
  json: {
    correlation_id:      randomUUID(),
    execution_id:        randomUUID(),
    agent_id:            'fao_reserve_recon_v1',
    agent_invoker_email: 'aisha.okonkwo@finagent-os.demo',
    risk_tier:           'RED',
    policy_sub_tier:     'CRITICAL',
    policy_rationale:    'FAO-REC-001 execution rollup over 7 assets. Outcomes: 3 ALLOW, 1 ALLOW_WITH_OBLIGATIONS, 3 REQUIRE_HUMAN. Worst-asset rule applied: execution outcome = REQUIRE_HUMAN (CRITICAL). Escalated assets: USDT (REQUIRE_HUMAN/STANDARD), SOL (REQUIRE_HUMAN/CRITICAL), ADA (REQUIRE_HUMAN/CRITICAL).',
    escalated_assets:    ['USDT', 'SOL', 'ADA'],
    execution_summary:   'Smoke test of HITL Gateway — simulated REQUIRE_HUMAN rollup'
  }
}];
